create table if not exists public.member_push_installations (id uuid primary key default gen_random_uuid(),installation_id text not null unique,profile_id uuid not null references public.profiles(id) on delete cascade,canteen_id uuid not null references public.canteens(id) on delete cascade,fcm_token text not null,platform text not null check(platform='android'),is_active boolean not null default true,binding_generation bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),last_seen_at timestamptz not null default now());
create index if not exists idx_member_push_installations_profile_active on public.member_push_installations(profile_id,is_active);
create index if not exists idx_member_push_installations_canteen_active on public.member_push_installations(canteen_id,is_active);
alter table public.member_push_installations enable row level security;
revoke all on public.member_push_installations from anon,authenticated;
grant select on public.member_push_installations to authenticated;
drop policy if exists member_push_installations_select_own on public.member_push_installations;
create policy member_push_installations_select_own on public.member_push_installations for select to authenticated using(profile_id=auth.uid() and canteen_id=public.current_canteen_id() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='employee' and p.status='active' and p.canteen_id=member_push_installations.canteen_id));
create or replace function public.register_member_push_installation(p_installation_id text,p_fcm_token text,p_platform text default 'android',p_binding_generation bigint default 1) returns jsonb language plpgsql security definer set search_path=public as $fn$ declare v_profile public.profiles%rowtype; v_row public.member_push_installations%rowtype; begin if auth.uid() is null then raise exception 'Authentication required.'; end if; if length(trim(coalesce(p_installation_id,'')))<8 then raise exception 'Invalid installation id.'; end if; if length(trim(coalesce(p_fcm_token,'')))<20 then raise exception 'Invalid FCM token.'; end if; if p_platform<>'android' then raise exception 'Unsupported push platform.'; end if; if coalesce(p_binding_generation,0)<1 then raise exception 'Invalid binding generation.'; end if; select * into v_profile from public.profiles where id=auth.uid() and role='employee' and status='active'; if not found or v_profile.canteen_id is null then raise exception 'Only active Members can register push installations.'; end if; insert into public.member_push_installations(installation_id,profile_id,canteen_id,fcm_token,platform,is_active,binding_generation,created_at,updated_at,last_seen_at) values(trim(p_installation_id),v_profile.id,v_profile.canteen_id,trim(p_fcm_token),p_platform,true,p_binding_generation,now(),now(),now()) on conflict(installation_id) do update set profile_id=excluded.profile_id,canteen_id=excluded.canteen_id,fcm_token=excluded.fcm_token,platform=excluded.platform,is_active=true,binding_generation=excluded.binding_generation,updated_at=now(),last_seen_at=now() where public.member_push_installations.binding_generation<=excluded.binding_generation returning * into v_row; if v_row.id is null then select * into v_row from public.member_push_installations where installation_id=trim(p_installation_id); return jsonb_build_object('ok',false,'stale',true,'installation_id',p_installation_id,'binding_generation',v_row.binding_generation); end if; return jsonb_build_object('ok',true,'stale',false,'installation_id',v_row.installation_id,'profile_id',v_row.profile_id,'canteen_id',v_row.canteen_id,'binding_generation',v_row.binding_generation); end; $fn$;
grant execute on function public.register_member_push_installation(text,text,text,bigint) to authenticated;
create or replace function public.deactivate_member_push_installation(p_installation_id text,p_binding_generation bigint default 1) returns boolean language plpgsql security definer set search_path=public as $fn$ begin if auth.uid() is null then return false; end if; update public.member_push_installations mpi set is_active=false,updated_at=now(),last_seen_at=now() where mpi.installation_id=trim(coalesce(p_installation_id,'')) and mpi.binding_generation<=coalesce(p_binding_generation,0) and ((mpi.profile_id=auth.uid() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='employee')) or exists(select 1 from public.profiles a where a.id=auth.uid() and a.role='admin' and a.status='active' and a.canteen_id=mpi.canteen_id)); return found; end; $fn$;
grant execute on function public.deactivate_member_push_installation(text,bigint) to authenticated;
create table if not exists public.member_push_delivery_outbox(id uuid primary key default gen_random_uuid(),notification_id uuid not null references public.notifications(id) on delete cascade,installation_id uuid not null references public.member_push_installations(id) on delete cascade,profile_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'pending' check(status in('pending','processing','sent','skipped','invalid_token','failed')),attempts integer not null default 0,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),sent_at timestamptz,unique(notification_id,installation_id));
create index if not exists idx_member_push_outbox_pending on public.member_push_delivery_outbox(status,created_at) where status in('pending','processing');
alter table public.member_push_delivery_outbox enable row level security;
revoke all on public.member_push_delivery_outbox from anon,authenticated;
create or replace function public.enqueue_member_push_delivery() returns trigger language plpgsql security definer set search_path=public as $fn$ begin insert into public.member_push_delivery_outbox(notification_id,installation_id,profile_id) select new.id,mpi.id,new.recipient_id from public.member_push_installations mpi join public.profiles p on p.id=mpi.profile_id where mpi.profile_id=new.recipient_id and mpi.canteen_id=new.canteen_id and mpi.is_active=true and p.role='employee' and p.status='active' on conflict(notification_id,installation_id) do nothing; return new; end; $fn$;
drop trigger if exists notifications_member_push_outbox on public.notifications;
create trigger notifications_member_push_outbox after insert on public.notifications for each row execute function public.enqueue_member_push_delivery();
create or replace function public.gocanteen_notification_scheduler() returns void language plpgsql security definer set search_path=public as $fn$ declare v_now timestamp:=now() at time zone 'Asia/Kolkata'; v_today date:=v_now::date; r record; v_target_date date; v_order_label text; begin if v_now::time>=time '18:00' then for r in select hd.id,hd.canteen_id,hd.holiday_date from public.holiday_dates hd where hd.holiday_date=v_today+1 loop perform public.notify_canteen_employees_for_canteen(r.canteen_id,'holiday_tomorrow:'||r.id::text,'holiday_tomorrow','Holiday Tomorrow',format('Tomorrow is a holiday — %s.',to_char(r.holiday_date,'DD Mon YYYY')),jsonb_build_object('holiday_date',r.holiday_date::text,'holiday_id',r.id,'holiday_source','declared')); end loop; end if; for r in select canteen_id,enabled,start_time,end_time,coalesce(order_for,'today') as order_for from public.order_window_settings where coalesce(enabled,false) and start_time is not null and end_time is not null loop v_target_date:=case when r.order_for='tomorrow' then v_today+1 else v_today end; v_order_label:=case when r.order_for='tomorrow' then 'Tomorrow''s' else 'Today''s' end; if to_char(v_now,'HH24:MI')=to_char(r.start_time,'HH24:MI') then perform public.notify_canteen_employees_for_canteen(r.canteen_id,'order_time_open:'||r.canteen_id::text||':'||v_target_date::text||':'||r.order_for,'order_time_open','Order Time Open',v_order_label||' orders are now open.',jsonb_build_object('business_date',v_target_date::text,'order_for',r.order_for,'order_window_state','open')); end if; if to_char(v_now,'HH24:MI')=to_char(r.end_time-interval '10 minutes','HH24:MI') then perform public.notify_canteen_employees_for_canteen(r.canteen_id,'order_time_closing_soon:'||r.canteen_id::text||':'||v_target_date::text||':'||r.order_for,'order_time_closing_soon','Order Time Closing Soon',v_order_label||' orders close in 10 minutes.',jsonb_build_object('business_date',v_target_date::text,'order_for',r.order_for,'order_window_state','closing_soon')); end if; if to_char(v_now,'HH24:MI')=to_char(r.end_time,'HH24:MI') then perform public.notify_canteen_employees_for_canteen(r.canteen_id,'order_time_closed:'||r.canteen_id::text||':'||v_target_date::text||':'||r.order_for,'order_time_closed','Order Time Closed',v_order_label||' orders are now closed.',jsonb_build_object('business_date',v_target_date::text,'order_for',r.order_for,'order_window_state','closed')); end if; end loop; end; $fn$;
do $outer$ begin perform cron.unschedule('gocanteen-notification-scheduler'); perform cron.schedule('gocanteen-notification-scheduler','* * * * *',$job$ select public.gocanteen_notification_scheduler(); select net.http_post(url:='https://cdrjfukxirkanrdklnli.supabase.co/functions/v1/deliver-member-push',headers:=jsonb_build_object('Content-Type','application/json'),body:='{}'::jsonb) as request_id; $job$); end; $outer$;
revoke all on function public.enqueue_member_push_delivery() from public,anon,authenticated;
revoke all on function public.gocanteen_notification_scheduler() from public,anon,authenticated;
